import{_ as r,a,b as o,c as i,d as s,e as n,f as l,g as m,h as c,i as d}from"./chunks/69f5d86e399a47fa6442.BWmsNKgX.js";import{_ as u}from"./chunks/1a42c0b21e1c29d406b4.BjpIRENm.js";import{_ as g,C as h,o as f,c as _,j as p,a as b,E as k,a5 as T}from"./chunks/framework.DNkHA0lr.js";const x=JSON.parse('{"title":"我搞砸了7个线上商业模式（但最终将其转化为了全职的创作者收入）","description":"","frontmatter":{"title":"我搞砸了7个线上商业模式（但最终将其转化为了全职的创作者收入）","originalTitle":"I Failed At 7 Online Business Models (And Turned It Into A Full-Time Creative Income)","date":"2022-06-04","originalUrl":"https://thedankoe.com/letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income/","minutes":12,"sourceHash":"e6b34c8fae1e6aa544c28b1351d9b02e008d8a2124e6d59bec46e89b2d0cccab","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income/"}]]},"headers":[],"relativePath":"letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income.md","filePath":"letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income.md"}'),w={name:"letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income.md"};function A(M,e,y,I,q,v){const t=h("ArticleMeta");return f(),_("div",null,[e[0]||(e[0]=p("h1",{id:"我搞砸了7个线上商业模式-但最终将其转化为了全职的创作者收入",tabindex:"-1"},[b("我搞砸了7个线上商业模式（但最终将其转化为了全职的创作者收入） "),p("a",{class:"header-anchor",href:"#我搞砸了7个线上商业模式-但最终将其转化为了全职的创作者收入","aria-label":'Permalink to "我搞砸了7个线上商业模式（但最终将其转化为了全职的创作者收入）"'},"​")],-1)),k(t),e[1]||(e[1]=T('<p><a href="https://www.youtube.com/embed/L9qh1-T_YVo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我从小就善于观察。</p><p>我知道肯定有更好的生活方式。</p><p>似乎我目光所及的每个角落……人们都<em>不快乐</em>。</p><p>对他们的职业、老板、配偶、孩子、同事、自己、清晨、夜晚、对一切都不满。</p><p>这也许只是我所接触的环境，又或者是我大脑的本能倾向，但某种东西让我对这种“默认”的生活方式避之不及。</p><p>抱怨自己拿到的烂牌并不会改变我的未来。</p><p>把主动权掌握在自己手中是唯一的出路。</p><p>个人责任、自我教育以及对主权的追求，是我在20岁前的人生中所倾注的心血。</p><p>如果每个人都被教导去看新闻、上大学、找工作、65岁退休、按部就班地做事——那难道不会导致每个人都得到相同的结果吗？</p><p>这难道不是全球性不快乐的根源吗？</p><p>只有一个选择：<strong>做和所有人完全相反的事。</strong></p><p>当所有人都把眼睛死死盯在电视上时，我把眼睛死盯在了在线教育者身上。</p><p>当所有人都下班后瘫在沙发上时，我一放学就径直去了健身房。</p><p>当所有人都任由有毒的主流新闻淹没大脑时，我却在阅读关于精神世界和实现我全部潜能的书籍。</p><h2 id="我人生的梦魇-传统的职业道路" tabindex="-1">我人生的梦魇：传统的职业道路 <a class="header-anchor" href="#我人生的梦魇-传统的职业道路" aria-label="Permalink to &quot;我人生的梦魇：传统的职业道路&quot;">​</a></h2><p>有一件事我是真的非常期待，那就是上大学。我知道这会给我机会去尝试新事物、结识新朋友，并最终：</p><p>推迟我必须靠自己建立可持续收入来源的时间节点。</p><p>在我踏入亚利桑那州立大学（ASU）校园的那一刻，我就知道倒计时已经开始了。</p><p>这是生死存亡的时刻。我必须学会<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">无需打工就能获得收入的必要技能</a>，否则就会落得和大家一样的下场。如果我不得不去找份工作，我知道每天8小时和极其耗费精力的工作，会让我几乎没有余力去摆脱这份工作。</p><p>我拼了命地想尝试不同的商业模式。</p><p>大一时，我和住在离我三个门远的宿舍哥们儿一起做了一个健身YouTube频道。</p><p>我们制作健身视频、教学视频和食物挑战视频（<a href="https://youtu.be/4UXTyg81u0c" target="_blank" rel="noreferrer">比如我做过的这个未公开的10,000卡路里挑战</a>）。</p><p>几个月后，我们决定放弃。大一期间，除了聚会、打游戏、上平面设计、市场营销、电影以及其他各种课程（看看我到底对什么感兴趣）之外，我没做太多其他事。</p><p>大约在那个时候，我和我的一群朋友因为在宿舍楼对面的停车楼里抽大麻被捕了。我有幸坐上了那位不太友善的警察的车，录了指纹，还被他盘问大麻是从哪来的（这是个有趣的故事，我们下次再聊）。</p><p>这是我人生中一个重要的转折点。我已经忘记了自己要避开传统职业道路的目标。放暑假回家时，我收到了一封法院寄来的信，给了我两个选择：</p><ol><li>上法庭为自己辩护，然后可能成为一名被定罪的重罪犯</li><li>支付大约5000到10000美元，参加一个让我连续3到6个月每周都要往杯子里尿尿（尿检）的项目</li></ol><p>这真把我吓得半死。我向父母隐瞒了这封信，独自在沉默中消化内心的煎熬。</p><p>就在那时，我买了埃克哈特·托利（Eckhart Tolle）的《当下的力量》。我死死盯着书页，希望它能减轻我的一些痛苦——它确实做到了。这是我为数不多真正不再在乎的时刻之一。我放下了。该发生的总会发生。</p><p>我重新找回了开辟自己道路的动力，又开始做YouTube视频了（对着镜头讲话的视频，有点像当时的Elliot Hulse），并在这个过程中继续学习灵性知识。</p><p>就像我尝试过的所有其他商业模式一样，这个也没搞成。</p><h2 id="失败-失败-再失败" tabindex="-1">失败，失败，再失败 <a class="header-anchor" href="#失败-失败-再失败" aria-label="Permalink to &quot;失败，失败，再失败&quot;">​</a></h2><p>大二那年，我迷上了摄影。我像疯了一样看YouTube视频自学，用暑假打工赚的钱买了一台相机，然后逮着什么拍什么。市中心的摩天大楼、长途徒步后的风景、大自然的微距特写。</p><p>我并不是真的喜欢拍照，我<em>真正</em>热爱的是修图。这个发现让我一头扎进了学习Photoshop的兔子洞，到了大三，我开始致力于把一些修好的图发到Instagram上。</p><p>我一次会在电脑前死磕6到8个小时，努力将脑海中的超现实画面变为现实。以下是一些成果：</p><p><img src="'+r+'" alt=""></p><p><img src="'+a+'" alt=""></p><p><img src="'+o+'" alt=""></p><p><img src="'+i+'" alt=""></p><p>这些大多只是素材图的缝合，有些包含了我自己拍的照片（比如建筑和飞机）。</p><p>我从没想过靠这个赚钱——但我最终在Instagram上获得了大约2500名粉丝。几个月后，我就对整个数字艺术感到厌倦了，但它让我学到了平面设计和视觉叙事的重要性，也让我意识到了用高质量内容在社交媒体上增长的可能性。</p><p>如果我当时有现在的认知，我本可以轻松做个课程，教别人怎么制作这些合成图。</p><p>同年，我又尝试了其他几个商业模式。</p><p><strong>1) 一家Facebook广告代运营机构</strong></p><p>我买了一门课，学习了获取客户、创建Facebook广告以及为本地企业做广告的基础知识。</p><p>在发了大约50封开发信，并在2到3次销售电话后依然没签下一个客户，我放弃了。</p><p><strong>2) 一家狂欢派对服装的无货源电商店</strong></p><p>大二时，我参加了人生中第一场狂欢派对，并接触到了整个EDM（电子舞曲）圈子（这也是为什么我后来专注工作和健身时痴迷于听回响贝斯Dubstep）。我对这个行业了如指掌，也知道大家对花哨（且布料极少）的衣服有需求。尤其是在“音乐节爆发季”。</p><p>我买了一门电商课程，教我品牌建设、文案写作、Shopify建站，以及如何寻找“好产品”。</p><p>我运用了之前学到的Facebook广告知识，花了大约100美元打广告，然后卖出了<strong>一件</strong>亮片胸罩（哈哈）。</p><p><img src="'+s+'" alt=""></p><p>在网上赚到的第一块钱感觉棒极了，但让顾客等上30天才能收到从中国发货的产品，这让我觉得自己像个垃圾。</p><p><strong>3) 自由职业网页设计</strong></p><p>事情从这里开始变得刺激了。那时候——在大四——我和另外6个家伙住在一栋旧的兄弟会房子里。没错……6个大老爷们挤在一栋房子里。里面有2间主卧，大家合住。</p><p>我上了一门网页开发入门课，它将我推向了人生的全新阶段。我爱上了写代码。我逃课、去学Udemy上的课程、上免费的编程课，最终在大约一个月内学完了大学这门课的全部教学大纲。我有95%的课都没去上，但依然是班里的第一名。</p><p>我如此热爱它的部分原因在于，我知道我可以用这项技能做自由职业，而且不管我毕不毕业，至少都能找到一份工作。</p><p>我尝试做自由职业，联系了亲朋好友，建了几个作品集网站，并拿下了一些廉价的客户（我总共赚了大约500美元）。</p><p><strong>那是大四——<em>我的时间不多了。</em></strong></p><p>我必须得搞出点名堂，否则就只能向“找份正经工作”的命运妥协。</p><p><strong>4) 两个电商品牌</strong></p><p>我决定把我做品牌、网页开发、平面设计和广告的技能结合起来，创建一个真正的品牌。</p><p>我知道程序员们整天都盯着屏幕——而这正是防蓝光眼镜开始在主流大众中流行的时候——所以我给我爸打了个电话。</p><p><em>“嘿，老爸……问你个事……我呃呃呃能借几千块钱吗？我保证会还你的，这是我全部的发财计划，听起来很靠谱对吧？”</em></p><p>我爸估计觉得我疯了，但他相信我，这让我真的很感激——不是很多人都有这样的机会。<strong>我绝不能浪费它。</strong></p><p>我去寻找完美的产品，下订单，等了30天收到货，拍了产品图（用上了我的摄影技巧！），然后开始花钱投广告和找网红推广。</p><p>这是我的一张广告图：</p><p><img src="'+n+'" alt=""></p><p>没错。那是一只刺猬。他的名字叫Momo。虽然外表带刺，但非常喜欢抱抱。他后来生病了——在我多次尝试用注射器喂食后——他还是去世了。</p><p>愿Momo安息。</p><p>眼镜很棒。我为这个产品感到自豪。但在那个时候，我完全是在把钱往广告这个无底洞里砸。我学着做网红推广，付钱让一个Meme（梗图）账号发广告，结果评论区所有人都在骂我是个小丑。这太伤人了，我再一次退出了。</p><p>这引发了我人生中又一个重大的低谷，就跟我被捕时一样。</p><p>我挥霍了我爸的钱，刷爆了我的第一张信用卡，而且看不到任何希望。我完蛋了。</p><p>唯一合乎逻辑的选择就是接受命运，用我之前学到的编程技能，去选找工作的B计划。</p><p>运气还不错，我很快就找到了一份网页设计的工作。那是一份轻松安逸的工作，教会了我运营一家网页设计机构到底需要什么。我利用在那里的空闲时间尝试拉客户，并取得了一些成功。</p><p>既然现在有钱进账了，我决定再尝试一个电商品牌。这次卖的是极简钱包（我和我的朋友们至今还在用，质量好极了。）</p><p>我甚至花了不少钱拍专业的产品图：</p><p><img src="'+l+'" alt=""></p><p><img src="'+m+'" alt=""></p><p>结果又一样……一单没出，浪费了钱，我也搞厌了。</p><p>就是在那个时候，我决定全力投入自由职业。</p><p>在这整个过程中有一段模糊的时期，我还尝试做过SEO代运营机构和内容营销机构，而且仍然在<em>稍微</em>尝试为我能接到的任何活儿找客户，主要是网页设计。</p><p>直到这一刻，我所积累的所有技能绝不能让我失望。</p><h2 id="一切都毫无意义-直到一切豁然开朗" tabindex="-1">一切都毫无意义，直到一切豁然开朗 <a class="header-anchor" href="#一切都毫无意义-直到一切豁然开朗" aria-label="Permalink to &quot;一切都毫无意义，直到一切豁然开朗&quot;">​</a></h2><p><img src="'+u+'" alt=""></p><p>尽管我有了一份薪水不错的工作，但我内心的那个小孩依然在向我嘶吼，让我一定要兑现自己的承诺。</p><p>我也许无法完全避开打工的命运，但我绝对可以在其他生活重担开始堆积之前，从这种生活中抽身而出。</p><p>我走进本地商户，重新联系了我的人脉网，尝试了在领英（LinkedIn）上开发客户，以及其他所有能试的方法。</p><p>通过这种方式，我每个月能签下2到3个客户，客单价在1500到2500美元之间。</p><p>随着我对我所帮助的企业（主要是服务型企业）有了更多了解，我也学到了一些关于邮件营销和文案写作的知识。</p><p>我调整了我的服务方案，开始搭建简单的服务漏斗。</p><p>一个包含落地页、选择加入表单（opt-in）和邮件序列的系统，能为承包商、律师、会计师、害虫防治人员等已经有线索但想把更多线索转化为通话和客户的人预约通话。</p><p>就是在这个时候，我开始提高价格（因为这是一个更具体的报价，效果也更好）。</p><p>设置这个漏斗我会收取 2500 到 5000 美元。构建它花的时间比建一个完整的网站还要少。</p><p>同样，这段记忆有点模糊了，但就是在这段时间我辞去了工作。</p><p>并没有我想象的那么令人兴奋……</p><p>几个月后，我转战 Twitter，开始发布内容，并在尝试在那里寻找网页设计/漏斗客户的同时，策划了一款自由职业产品。这时我的细分领域（niche）转向了创作者（creators）、教练和自由职业者。我很了解他们，喜欢和他们合作，并且能为他们带来极佳的成果。</p><p>在过去的 4 年里，我打造了各种产品，转型了我的个人品牌，测试了不同的报价，然后就走到了今天。</p><p>这是一个大致的时间线：</p><ul><li>我的自由职业收入达到了 6 位数</li><li>我打造了我的自由职业产品，积累了受众，并开始通过信息产品每月额外赚取约 3000 美元</li><li>我创建了一个教网页设计的配套产品</li><li>我的 Twitter 粉丝达到了 10000 人，并创建了一个关于我如何在 Twitter 上增长并获取客户的产品（这个课程包现在包含在 MMHQ 中 – <a href="https://www.modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">Koe Letter 读者花 5 美元即可加入</a>）</li><li>我推出了一款实体手帐（planner），但厌倦了实体产品电商以及从家里发货，于是制作了免费的数字版本（The Power Planner）</li></ul><p><img src="'+c+'" alt=""></p><p><img src="'+d+'" alt=""></p><ul><li>我的数字产品销售额达到了 6 位数</li><li>我将自由职业报价转向了营销咨询报价——因为创作者喜欢亲力亲为，这也为我腾出了更多时间</li><li>我创立了 Modern Mastery HQ</li><li>我实现了首个月入 5 万美元，并作为一家一人企业（one-person business）获得了每年稳定的 30 万到 50 万美元收入</li><li>Modern Mastery 成员增长到了 1000 人</li><li>我停止了咨询，准备在 6 月 14 日（不到 2 周的时间！）推出 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>——我的学校，主打快速技能获取、受众积累、内容创作以及其他相关内容</li></ul><p>一开始什么都没发生。然后一切接踵而至。</p><p>我们将在下一期《Koe Letter》中详细探讨这个业务进展（以及如果你刚刚起步，我会建议你在哪些地方采取不同的做法）。</p><h2 id="从十年失败中汲取的-7-个快速教训" tabindex="-1">从十年失败中汲取的 7 个快速教训 <a class="header-anchor" href="#从十年失败中汲取的-7-个快速教训" aria-label="Permalink to &quot;从十年失败中汲取的 7 个快速教训&quot;">​</a></h2><p>我在这段旅程中学到了很多教训，但以下几个我认为影响最深远：</p><p><strong>1) 起初毫无头绪，接着豁然开朗</strong></p><p>我会让这条推文来诉说生活这个悖论：</p><blockquote><p>完美的想法总是出现在一段迷茫期之后。起初毫无头绪，接着豁然开朗。这是周期性的，且不可避免。享受它吧。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1532291439828271104?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 2, 2022</a></p></blockquote><p><strong>2) 自己想办法搞定（Figure It Out）</strong></p><p>任何事情都是可能的。确实如此。你有无限的机会和教育资源触手可及。你可能没看到，是因为你还没有敞开心扉去接受那种可能性。</p><p>永远不要停止学习。你<strong>总是</strong>应该手头有一个正在进行的项目，同时通过自学来了解如何构建这个项目。这就是你<em>快速</em>学习的方式。</p><p><strong>3) 不要害怕从头开始</strong></p><p>生活还要继续。如果你现在试图建立的业务没有带来结果（而且你也觉得这不会是你一辈子要做的事），那就换条路走。</p><p>尝试些新东西。和几个朋友去喝个烂醉，然后顿悟下一步该怎么走（这话听听就好，别太当真，哈哈）。</p><p><strong>4) 拥抱不确定和未知的道路</strong></p><p>任何值得拥有的东西都是不可预测的。如果你正在读这篇文章，说明你本来就不适合走每个人都在走的那条传统道路。你知道这一切之外还有更广阔的天地——希望我已经为你打开了生活中更多可能性的这扇门。</p><p>不确定性会让你<em>极度</em>胡思乱想（内耗）。拥抱这一点。肌肉就是在阻力、拉伸和充足的恢复中练成的。</p><p><strong>5) 尝试一切</strong></p><p>买书。听从社交媒体上的建议。尝试每一个能想象到的商业模式。在网上发布内容。</p><p>你的任务是找到你喜欢解决的问题、你喜欢谈论的话题，以及它们的交集所在。这就是你开始发掘毕生事业的方式。</p><p><strong>6) 给予，给予，再给予</strong></p><p>在开始的时候，免费工作。为自己做项目。为朋友做项目。为虚构的业务做项目。与别人通话。在 Twitter 上建立人脉。</p><p>倾囊相授你所有的价值，不求任何回报。好事自然会发生。</p><p><strong>7) 放手一搏——然后再搏一次</strong></p><p>绝对没有任何东西能阻止你展示自己，除了你自己。</p><p>习惯被拒绝。</p><p>最坏的结果能怎样？无非是你得再试一次？你学到了另一个宝贵的教训？你的射击变得更加精准了？</p><p>放手去搏吧。</p><p>感谢你的阅读——我希望这能给你的生活带来一些启发。</p><p>启发是强大的。</p><p>别浪费它。</p><p>— Dan Koe</p><p><strong>本周动态</strong></p><p>一个关于如何不再在乎别人怎么想的新 YouTube 视频已上线。</p><p><a href="https://youtu.be/Sl0AvS8WJ54" target="_blank" rel="noreferrer">点击观看。</a></p><p>一期关于深耕细分领域和创造属于你自己的现实的播客已发布。</p><p><a href="https://open.spotify.com/episode/1ud7ipZwgV6V7ZwcOowUAA?si=0b59823975684cf5" target="_blank" rel="noreferrer">点击收听。</a></p><p>MMHQ 内安排了一项新挑战、一篇关于作为创作者保持真实性的文章，以及本月与 Dakota Robertson 合作的关于开启代写业务的培训。</p><p><a href="https://modernmastery.co/community/modern-mastery-hq-special" target="_blank" rel="noreferrer">点击这里花 5 美元加入。</a></p><p>我的学校将于 6 月 14 日开学，主打快速获取现代技能、品牌塑造，以及创建内容生态系统，从而为你作为创意人士、营销人员或个体创业者带来高薪业务。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">11 日前点击这里锁定折扣名额。</a></p><hr><p><a href="/en/letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',144))])}const V=g(w,[["render",A]]);export{x as __pageData,V as default};
